  sum = tap.rgb; weight = tap.a;
  tap = addTap(sum, weight, uv, vec2<f32>(-0.866,  0.500), radiusPixels);
  sum = tap.rgb; weight = tap.a;
  tap = addTap(sum, weight, uv, vec2<f32>( 0.500,  0.866), radiusPixels);
  sum = tap.rgb; weight = tap.a;
  tap = addTap(sum, weight, uv, vec2<f32>( 1.000,  0.000), radiusPixels);
  sum = tap.rgb; weight = tap.a;
  tap = addTap(sum, weight, uv, vec2<f32>( 0.500, -0.866), radiusPixels);
  sum = tap.rgb; weight = tap.a;
  tap = addTap(sum, weight, uv, vec2<f32>(-0.500, -0.866), radiusPixels);
  sum = tap.rgb; weight = tap.a;
  tap = addTap(sum, weight, uv, vec2<f32>(-1.000,  0.000), radiusPixels);
  sum = tap.rgb; weight = tap.a;
